function filmModel(record){
 const m={...record};
 for(const key of ['title','originalTitle','genre','director','description','hook','plot','review','reason','source','where','status'])m[key]=String(record[key]??'');
 m.title=m.title||'Без названия';m.rating=Math.max(0,Math.min(10,Math.round(Number(record.rating)||0)));
 m.cast=(Array.isArray(record.cast)?record.cast:[]).map(filmText);m.countries=(Array.isArray(record.countries)?record.countries:[]).map(filmText);m.tags=(Array.isArray(record.tags)?record.tags:[]).map(filmText);
 m.viewed=Boolean(record.viewed||record.status==='Посмотрел');m.pinned=Boolean(record.pinned);m.skipped=Boolean(record.skipped);m.rewatch=Boolean(record.rewatch);m.removed=Boolean(record.removed);
 return m;
}
