   paintRating(m.rating);q('[data-movie-rating]').value=String(m.rating);q('[data-movie-rating]').disabled=blocked;
   q('[data-movie-status]').textContent=m.skipped?'Не интересно':m.viewed?'Просмотрено':m.status==='Смотрю'?'Смотрю':'В планах';
   const viewed=q('[data-movie-viewed]');viewed.textContent=m.viewed?'В планы':'Просмотрено';viewed.setAttribute('aria-pressed',String(m.viewed));
   q('[data-movie-rewatch]').setAttribute('aria-pressed',String(m.rewatch));q('[data-movie-rewatch]').textContent=m.rewatch?'В планах пересмотреть':'Пересмотреть';q('[data-movie-skip]').setAttribute('aria-pressed',String(m.skipped));q('[data-movie-clear]').disabled=!m.rating||blocked;
   q('[data-movie-review-wrap]').hidden=!m.rating;const review=q('[data-movie-review]');review.disabled=blocked;if(this.shadowRoot.activeElement!==review)review.value=m.review;
   q('[data-movie-reason-copy]').textContent=m.reason;q('[data-movie-reason-copy]').hidden=!m.reason;
   for(const pin of [q('[data-movie-pin]'),this.shadowRoot.querySelector('[data-bookmark]')]){pin.setAttribute('aria-pressed',String(m.pinned));pin.setAttribute('aria-label',`${m.pinned?'Открепить':'Закрепить'} фильм: ${m.title}`);}
   this.shadowRoot.querySelector('.film').hidden=m.removed;this.shadowRoot.querySelector('.movie-removed').hidden=!m.removed;
